/** Derive observed_confidence from analyze-emitted fields without an LLM.
 *  Rule: max conviction across factor_views; fall back to 'low' when no
 *  conviction is set. This makes the gate's input deterministic without
 *  changing the scenario-analyst prompt (ADR-0035 explicitly forbids the
 *  gate from using LLM output to set this layer). */
function deriveObservedConfidence(scenario: GateScenarioInput): ConfidenceLevel {
  const views = scenario.factor_views ?? [];
  let best: ConfidenceLevel = 'low';
  let bestRank = CONFIDENCE_RANK.low;
  for (const v of views) {
    const conviction = v.conviction;
    if (conviction === 'low' || conviction === 'medium' || conviction === 'high') {
      const r = CONFIDENCE_RANK[conviction];
      if (r > bestRank) {
        bestRank = r;
        best = conviction;
      }
    }
  }
  return best;
}

